#!/usr/bin/env python3
# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""linkcheck: resolve the references between Markdown documents, deterministically.

Checks three things across configured repositories, offline:

1. every reference (path, path at a branch, open-question id, commit id,
   trail number) resolves;
2. every document or question listed under a "Related" heading or field links
   back;
3. explicit assertions (inline HTML comments, or rows of a sidecar TSV for
   documents this repository may not edit) do not give one key two values.

It judges no meaning. See README.md for the conventions and the limits.
"""
from __future__ import annotations

import argparse
import bisect
import hashlib
import posixpath
import re
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path

HERE = Path(__file__).resolve().parent
DEFAULT_REPOS = HERE / 'repos.tsv'
DEFAULT_ASSERTIONS = HERE / 'assertions.tsv'
DEFAULT_QUESTIONS = 'praxis:OPENQUESTIONS.md'

KNOWN_EXT = {
    'md', 'tsv', 'csv', 'py', 'rs', 'toml', 'yml', 'yaml', 'json', 'jsonl',
    'html', 'svg', 'txt', 'pdf', 'sh', 'js', 'ts', 'css', 'cff', 'xml',
    'parquet', 'sql',
}
SIDECAR_COLUMNS = [
    'key', 'value', 'date', 'repo', 'ref', 'commit', 'path', 'source',
    'quote', 'quote_sha256', 'by',
]


# --------------------------------------------------------------------------
# Escapes shared by the sidecar TSV and the inline quote attribute.

def unescape(text: str) -> str:
    out, i = [], 0
    while i < len(text):
        ch = text[i]
        if ch == '\\' and i + 1 < len(text):
            nxt = text[i + 1]
            out.append({'n': '\n', 't': '\t', '\\': '\\'}.get(nxt, '\\' + nxt))
            i += 2
            continue
        out.append(ch)
        i += 1
    return ''.join(out)


def sha256(text: str) -> str:
    return hashlib.sha256(text.encode('utf-8')).hexdigest()


# --------------------------------------------------------------------------
# Repositories and git, read-only.

@dataclass
class Repo:
    name: str
    root: Path
    aliases: tuple[str, ...]

    @property
    def available(self) -> bool:
        return (self.root / '.git').exists()


class Repos:
    def __init__(self, repos: list[Repo], home: str):
        self.repos = {r.name: r for r in repos}
        self.home = home
        self.lookup: dict[str, str] = {}
        for r in repos:
            for n in (r.name, *r.aliases):
                self.lookup[n.lower()] = r.name
        self._git: dict[tuple, object] = {}

    @classmethod
    def load(cls, path: Path, home: str = 'praxis') -> 'Repos':
        repos = []
        for line in path.read_text(encoding='utf-8').splitlines():
            if not line.strip() or line.startswith('#'):
                continue
            cols = line.split('\t')
            if cols[0] == 'name':
                continue
            aliases = tuple(a for a in (cols[2].split(',') if len(cols) > 2 else []) if a)
            root = (path.parent / cols[1]).resolve()
            repos.append(Repo(cols[0], root, aliases))
        return cls(repos, home)

    def name_of(self, word: str) -> str | None:
        return self.lookup.get(word.lower())

    def git(self, repo: str, *args: str) -> subprocess.CompletedProcess:
        key = (repo, args)
        if key not in self._git:
            self._git[key] = subprocess.run(
                ['git', '-C', str(self.repos[repo].root), *args],
                capture_output=True, check=False)
        return self._git[key]  # type: ignore[return-value]

    def commit_of(self, repo: str, ref: str | None) -> str | None:
        """A ref name to a commit. A branch name falls back to origin/<name>."""
        if not self.repos[repo].available:
            return None
        names = ['HEAD'] if ref is None else [ref, 'origin/' + ref]
        for n in names:
            p = self.git(repo, 'rev-parse', '--verify', '--quiet', n + '^{commit}')
            if p.returncode == 0:
                return p.stdout.decode().strip()
        return None

    def read(self, doc: 'Doc') -> bytes | None:
        repo = self.repos.get(doc.repo)
        if repo is None or not repo.root.exists():
            return None
        if doc.ref is None:
            f = repo.root / doc.path
            return f.read_bytes() if f.is_file() else None
        commit = self.commit_of(doc.repo, doc.ref)
        if commit is None:
            return None
        p = self.git(doc.repo, 'show', f'{commit}:{doc.path}')
        return p.stdout if p.returncode == 0 else None

    def exists(self, repo: str, ref: str | None, path: str, disk: bool) -> bool:
        if disk:
            return (self.repos[repo].root / path).exists()
        commit = self.commit_of(repo, ref)
        if commit is None:
            return False
        return self.git(repo, 'cat-file', '-e', f'{commit}:{path.rstrip("/")}').returncode == 0

    def has_commit(self, repo: str, sha: str) -> bool:
        if not self.repos[repo].available:
            return False
        return self.git(repo, 'rev-parse', '--verify', '--quiet', sha + '^{commit}').returncode == 0


@dataclass(frozen=True)
class Doc:
    repo: str
    ref: str | None   # None: the working-tree file on disk
    path: str

    @classmethod
    def parse(cls, spec: str) -> 'Doc':
        m = re.match(r'^(?P<repo>[\w.-]+)(?:@(?P<ref>[^:]+))?:(?P<path>.+)$', spec)
        if not m:
            raise ValueError(f'bad document spec {spec!r}; want repo[@ref]:path')
        return cls(m['repo'], m['ref'], m['path'])

    def __str__(self) -> str:
        return f'{self.repo}@{self.ref}:{self.path}' if self.ref else f'{self.repo}:{self.path}'


# --------------------------------------------------------------------------
# Extraction.

@dataclass
class Ref:
    kind: str            # path | qid | commit | trail
    line: int
    raw: str
    offset: int
    para: int
    status: str = 'ok'   # ok | unresolved | unchecked
    detail: str = ''
    # path
    repo: str | None = None
    ref: str | None = None
    path: str | None = None
    disk: bool = False
    explicit_repo: bool = False
    link: bool = False
    # qid / trail
    number: int | None = None

    def target(self) -> tuple | None:
        if self.kind == 'path' and self.repo and self.path:
            return ('path', self.repo, self.path)
        if self.kind == 'qid':
            return ('qid', self.number)
        return None

    def shown(self) -> str:
        if self.kind == 'path' and self.repo:
            at = f'@{self.ref}' if self.ref else ''
            return f'{self.repo}{at}:{self.path}'
        return self.raw


@dataclass
class Assertion:
    key: str
    value: str
    date: str
    source: str
    where: str
    line: int
    origin: str          # inline | sidecar
    problems: list[str] = field(default_factory=list)


def mask(text: str, pattern: re.Pattern) -> str:
    return pattern.sub(lambda m: re.sub(r'[^\n]', ' ', m.group(0)), text)


FENCE = re.compile(r'^([ \t]*)(```|~~~)[^\n]*\n.*?^\1\2[^\n]*$', re.M | re.S)
COMMENT = re.compile(r'<!--.*?-->', re.S)
ASSERT = re.compile(r'<!--\s*assert\b(.*?)-->', re.S)
ATTR = re.compile(r'([\w-]+)=(?:"([^"]*)"|(\S+))')
SPAN = re.compile(r'`([^`\n]+)`')
LINK = re.compile(r'\]\(([^)\s]+)\)')
BRANCH = re.compile(r'\bbranch\s+`([^`\n]+)`', re.I)
QID = re.compile(r'(?<![\w-])Q(\d{1,3})(?![\w-])')
COMMIT = re.compile(r'(?<![\w./:-])([0-9a-f]{7,40})(?![\w/-])')
TRAIL = re.compile(r'\b[Tt]rails?\s+#?(\d+)\b|\b[Tt]rail\b[^\n#.]{0,60}?#(\d+)\b')
PARA_START = re.compile(r'\n[ \t]*\n|\n(?=[ \t]*(?:[-*+]|\d+[.)])[ \t])|\n(?=#{1,6}[ \t])')


class Text:
    """A document's text with line and paragraph lookup."""

    def __init__(self, raw: str):
        self.raw = raw
        self.masked = mask(mask(raw, FENCE), COMMENT)
        self.line_starts = [0] + [m.end() for m in re.finditer(r'\n', raw)]
        self.para_starts = [0] + [m.end() for m in PARA_START.finditer(self.masked)]

    def line(self, offset: int) -> int:
        return bisect.bisect_right(self.line_starts, offset)

    def para(self, offset: int) -> int:
        return bisect.bisect_right(self.para_starts, offset)


def path_candidate(s: str) -> tuple[str | None, str] | None:
    """Return (repo-prefix or None, path) when s looks like a file path."""
    s = s.strip().rstrip('.,;')
    if '://' in s or s.startswith(('mailto:', '#')):
        return None
    s = s.split('#', 1)[0]
    if not s or re.search(r'[\s*<>{}$|"\'()\[\]=]', s):
        return None
    prefix = None
    m = re.match(r'^([A-Za-z][\w-]*):(.+)$', s)
    if m:
        prefix, s = m.group(1), m.group(2)
    s = re.sub(r'(\.\w+):\d+(?:-\d+)?$', r'\1', s)
    if not re.match(r'^[\w.~/-]+$', s):
        return None
    ext = s.rsplit('.', 1)[-1].lower() if '.' in s.rsplit('/', 1)[-1] else ''
    if s.endswith('/'):
        if s.count('/') < 1 or s == '/':
            return None
    elif ext not in KNOWN_EXT:
        return None
    return prefix, s


def word_before(masked: str, offset: int) -> str:
    m = re.search(r'([A-Za-z][\w-]*)[\s(*]{0,6}$', masked[max(0, offset - 40):offset])
    return m.group(1) if m else ''


class Checker:
    def __init__(self, repos: Repos, questions: Doc, trails: dict[int, str] | None = None):
        self.repos = repos
        self.questions = questions
        self.trails = trails
        qbytes = repos.read(questions)
        self.qtext = qbytes.decode('utf-8', 'replace') if qbytes is not None else None
        self.qsections = self._sections(self.qtext) if self.qtext is not None else {}

    @staticmethod
    def _sections(text: str) -> dict[int, tuple[int, int]]:
        heads = [(m.start(), len(m.group(1)), int(m.group(2)))
                 for m in re.finditer(r'^(#{1,6})[ \t]+Q(\d+)\b', text, re.M)]
        all_heads = [(m.start(), len(m.group(1))) for m in re.finditer(r'^(#{1,6})[ \t]', text, re.M)]
        out = {}
        for start, level, n in heads:
            end = next((s for s, lv in all_heads if s > start and lv <= level), len(text))
            out.setdefault(n, (start, end))
        return out

    # ---- extraction -------------------------------------------------------
    def extract(self, doc: Doc, raw: str) -> tuple[Text, list[Ref], list[Assertion]]:
        t = Text(raw)
        refs: list[Ref] = []
        assertions = [self._inline_assertion(doc, t, m) for m in ASSERT.finditer(raw)]

        branch_spans = {m.start(1) - 1 for m in BRANCH.finditer(t.masked)}
        for rx, is_link in ((SPAN, False), (LINK, True)):
            for m in rx.finditer(t.masked):
                if not is_link and m.start() in branch_spans:
                    continue
                cand = path_candidate(m.group(1))
                if cand is None:
                    continue
                prefix, path = cand
                r = Ref('path', t.line(m.start()), m.group(1), m.start(), t.para(m.start()), link=is_link)
                repo = self.repos.name_of(prefix) if prefix else None
                if prefix and repo is None:
                    continue  # "word:thing" that is not a configured repo
                if repo is None and not is_link:
                    repo = self.repos.name_of(word_before(t.masked, m.start()))
                r.repo, r.path, r.explicit_repo = repo, path, repo is not None
                refs.append(r)
        refs.sort(key=lambda r: r.offset)

        for m in BRANCH.finditer(t.masked):
            para = t.para(m.start())
            prior = [r for r in refs if r.kind == 'path' and r.offset < m.start()
                     and r.para == para and r.ref is None]
            if prior:
                prior[-1].ref = m.group(1)

        for r in refs:
            self._resolve_path(doc, r)

        in_questions_repo = doc.repo == self.questions.repo
        for m in QID.finditer(t.masked):
            after = t.masked[m.end():m.end() + 6]
            if re.match(r"\s?(?:20\d\d|FY|'\d\d)", after):
                continue
            if not in_questions_repo:
                ls = t.line_starts[t.line(m.start()) - 1]
                le = t.masked.find('\n', m.start())
                ctx = t.masked[ls:le if le >= 0 else None].lower()
                if not any(w in ctx for w in ('question', 'praxis', 'openquestions')):
                    continue
            r = Ref('qid', t.line(m.start()), m.group(0), m.start(), t.para(m.start()), number=int(m.group(1)))
            if self.qtext is None:
                r.status, r.detail = 'unchecked', f'questions file {self.questions} unreadable'
            elif r.number not in self.qsections:
                r.status, r.detail = 'unresolved', f'no heading Q{r.number} in {self.questions}'
            refs.append(r)

        paths = [r for r in refs if r.kind == 'path']
        for m in COMMIT.finditer(t.masked):
            sha = m.group(1)
            if not (re.search(r'[a-f]', sha) and re.search(r'\d', sha)):
                continue
            para = t.para(m.start())
            prior = [r for r in paths if r.offset < m.start() and r.para == para and r.repo]
            repo = prior[-1].repo if prior else doc.repo
            r = Ref('commit', t.line(m.start()), sha, m.start(), para, repo=repo)
            if not self.repos.repos.get(repo) or not self.repos.repos[repo].available:
                r.status, r.detail = 'unchecked', f'repository {repo} not checked out'
            elif not self.repos.has_commit(repo, sha):
                elsewhere = sorted(n for n, rp in self.repos.repos.items()
                                   if n != repo and rp.available and self.repos.has_commit(n, sha))
                r.status = 'unresolved'
                r.detail = f'no commit {sha} in {repo}' + (f' (exists in {", ".join(elsewhere)})' if elsewhere else '')
            refs.append(r)

        for m in TRAIL.finditer(t.masked):
            n = int(m.group(1) or m.group(2))
            r = Ref('trail', t.line(m.start()), m.group(0).strip(), m.start(), t.para(m.start()), number=n)
            if self.trails is None:
                r.status, r.detail = 'unchecked', 'no trail snapshot given (--trails)'
            elif n not in self.trails:
                r.status, r.detail = 'unresolved', f'trail {n} not in snapshot'
            refs.append(r)

        refs.sort(key=lambda r: (r.offset, r.kind))
        return t, refs, assertions

    def _resolve_path(self, doc: Doc, r: Ref) -> None:
        path = r.path or ''
        if path.startswith(('~', '/')):
            r.status, r.detail, r.repo = 'unchecked', 'outside the configured repositories', None
            return
        docdir = posixpath.dirname(doc.path)

        def norm(p: str) -> str:
            n = posixpath.normpath(p)
            return n + '/' if p.endswith('/') and not n.endswith('/') else n

        def attempt(repo: str, cands: list[str]) -> bool:
            rp = self.repos.repos[repo]
            if not rp.root.exists():
                r.status, r.detail, r.repo, r.path = 'unchecked', f'repository {repo} not checked out', repo, cands[0]
                return True
            same = repo == doc.repo
            ref = r.ref if r.ref else (doc.ref if same else None)
            disk = same and r.ref is None and doc.ref is None
            if not disk and self.repos.commit_of(repo, ref) is None:
                r.status, r.detail = 'unresolved', f'ref {ref or "HEAD"} not found in {repo}'
                r.repo, r.ref, r.path = repo, ref, cands[0]
                return True
            for c in cands:
                if c.startswith('../'):
                    continue
                if self.repos.exists(repo, ref, c, disk):
                    r.repo, r.ref, r.path, r.disk, r.status = repo, ref, c, disk, 'ok'
                    return True
            r.repo, r.ref, r.path, r.disk = repo, ref, cands[0], disk
            return False

        if r.explicit_repo:
            cands = [norm(path)] if r.repo != doc.repo else self._local_cands(path, docdir, r.link, norm)
            if not attempt(r.repo, cands):
                r.status = 'unresolved'
                r.detail = f'not found at {r.repo}@{r.ref or ("working tree" if r.disk else "HEAD")}'
            return
        cands = self._local_cands(path, docdir, r.link, norm)
        r.repo = doc.repo
        if attempt(doc.repo, cands):
            return
        first, _, rest = path.partition('/')
        other = self.repos.name_of(first) if rest else None
        if other is not None:
            r.explicit_repo = True
            if attempt(other, [norm(rest)]):
                return
        r.status = 'unresolved'
        r.detail = f'not found at {r.repo}@{r.ref or ("working tree" if r.disk else "HEAD")}'

    @staticmethod
    def _local_cands(path, docdir, link, norm):
        rel = norm(posixpath.join(docdir, path)) if docdir else norm(path)
        root = norm(path)
        order = [rel, root] if link else [root, rel]
        return list(dict.fromkeys(order))

    def _inline_assertion(self, doc: Doc, t: Text, m: re.Match) -> Assertion:
        attrs = {a.group(1): (a.group(2) if a.group(2) is not None else a.group(3))
                 for a in ATTR.finditer(m.group(1))}
        a = Assertion(attrs.get('key', ''), attrs.get('value', ''), attrs.get('date', ''),
                      attrs.get('source', ''), str(doc), t.line(m.start()), 'inline')
        for req in ('key', 'value', 'date', 'source'):
            if not attrs.get(req):
                a.problems.append(f'missing {req}=')
        if 'quote' in attrs:
            quote = unescape(attrs['quote'])
            if quote not in mask(t.raw, COMMENT):
                a.problems.append('quote not found verbatim in the document')
        return a

    # ---- sidecar ------------------------------------------------------------
    def sidecar(self, path: Path) -> list[Assertion]:
        out = []
        rows = [l for l in path.read_text(encoding='utf-8').splitlines()
                if l.strip() and not l.startswith('#')]
        if not rows:
            return out
        header = rows[0].split('\t')
        if header != SIDECAR_COLUMNS:
            raise ValueError(f'{path}: header must be {SIDECAR_COLUMNS}')
        for i, line in enumerate(rows[1:], start=2):
            row = dict(zip(header, line.split('\t')))
            doc = Doc(row['repo'], row['ref'] or None, row['path'])
            a = Assertion(row['key'], row['value'], row['date'], row['source'],
                          f'{doc} (sidecar {path.name} row {i})', 0, 'sidecar')
            quote = unescape(row.get('quote', ''))
            if not quote:
                a.problems.append('sidecar row has no quote')
            elif sha256(quote) != row.get('quote_sha256', ''):
                a.problems.append('quote_sha256 does not match the quote')
            repo = self.repos.repos.get(doc.repo)
            if repo is None or not repo.available:
                a.problems.append(f'repository {doc.repo} unavailable; quote unchecked')
                out.append(a)
                continue
            if row.get('commit'):
                pinned = self.repos.read(Doc(doc.repo, row['commit'], doc.path))
                if pinned is None:
                    a.problems.append(f'not readable at pinned commit {row["commit"][:12]}')
                elif quote and quote.encode() not in pinned:
                    a.problems.append(f'quote not at pinned commit {row["commit"][:12]}')
            data = self.repos.read(doc)
            if data is None:
                a.problems.append(f'not readable at {doc}')
            elif quote:
                idx = data.find(quote.encode())
                if idx < 0:
                    a.problems.append(f'quote no longer at {doc.ref or "working tree"}')
                else:
                    a.line = data[:idx].count(b'\n') + 1
                    a.where = f'{doc} (sidecar {path.name} row {i})'
            out.append(a)
        return out

    # ---- reciprocity ------------------------------------------------------
    def related_blocks(self, t: Text) -> list[tuple[int, int]]:
        blocks = []
        lines = t.masked.split('\n')
        starts = t.line_starts
        for i, line in enumerate(lines):
            h = re.match(r'^(#{1,6})[ \t]+Related\b', line, re.I)
            if h:
                level = len(h.group(1))
                j = i + 1
                while j < len(lines):
                    hh = re.match(r'^(#{1,6})[ \t]', lines[j])
                    if hh and len(hh.group(1)) <= level:
                        break
                    j += 1
                blocks.append((starts[i], starts[j] if j < len(starts) else len(t.raw)))
                continue
            f = re.match(r'^([ \t]*)(?:[-*+][ \t]+)?\*\*Related:?\*\*', line, re.I)
            if f:
                indent = len(f.group(1))
                j = i + 1
                while j < len(lines) and lines[j].strip() and \
                        len(lines[j]) - len(lines[j].lstrip()) > indent and not lines[j].lstrip().startswith('#'):
                    j += 1
                blocks.append((starts[i], starts[j] if j < len(starts) else len(t.raw)))
        return blocks

    def source_unit(self, doc: Doc, offset: int) -> tuple:
        if doc == self.questions or (doc.repo == self.questions.repo and doc.path == self.questions.path):
            for n, (s, e) in sorted(self.qsections.items()):
                if s <= offset < e:
                    return ('qid', n)
        return ('path', doc.repo, doc.path)

    def reciprocity(self, doc: Doc, t: Text, refs: list[Ref]) -> list[tuple]:
        findings = []
        for start, end in self.related_blocks(t):
            src = self.source_unit(doc, start)
            seen = set()
            for r in refs:
                if not (start <= r.offset < end) or r.status != 'ok':
                    continue
                tgt = r.target()
                if tgt is None or tgt == src or tgt in seen:
                    continue
                if tgt[0] == 'path' and not tgt[2].endswith('.md'):
                    continue
                seen.add(tgt)
                body = self.unit_text(tgt, r)
                if body is None:
                    continue
                tdoc, ttext = body
                _, trefs, _ = self.extract(tdoc, ttext)
                back = {x.target() for x in trefs}
                if src not in back:
                    findings.append((self.unit_name(src), self.unit_name(tgt, r), str(doc), r.line))
        return findings

    def unit_text(self, tgt: tuple, r: Ref) -> tuple[Doc, str] | None:
        if tgt[0] == 'qid':
            s, e = self.qsections[tgt[1]]
            # Blank out everything outside the section so offsets and lines hold.
            text = ''.join(c if (s <= i < e or c == '\n') else ' ' for i, c in enumerate(self.qtext))
            return self.questions, text
        tdoc = Doc(tgt[1], None if r.disk else (r.ref or 'HEAD'), tgt[2])
        data = self.repos.read(tdoc)
        return (tdoc, data.decode('utf-8', 'replace')) if data is not None else None

    def unit_name(self, unit: tuple, r: Ref | None = None) -> str:
        if unit[0] == 'qid':
            return f'Q{unit[1]}'
        if r is not None:
            return r.shown()
        return f'{unit[1]}:{unit[2]}'


# --------------------------------------------------------------------------
# Running and reporting.

@dataclass
class Result:
    lines: list[str]
    failures: int


def run(docs: list[Doc], repos: Repos, questions: Doc, sidecar: Path | None,
        trails: dict[int, str] | None = None) -> Result:
    ck = Checker(repos, questions, trails)
    unresolved, unchecked, oneway, problems = [], [], [], []
    assertions: list[Assertion] = []
    counts = {'ok': 0, 'unresolved': 0, 'unchecked': 0}
    missing_docs = []
    for doc in sorted(set(docs), key=str):
        data = repos.read(doc)
        if data is None:
            missing_docs.append(str(doc))
            continue
        t, refs, inl = ck.extract(doc, data.decode('utf-8', 'replace'))
        assertions += inl
        for r in refs:
            counts[r.status] += 1
            row = (str(doc), r.line, r.kind, r.raw, r.detail)
            if r.status == 'unresolved':
                unresolved.append(row)
            elif r.status == 'unchecked':
                unchecked.append(row)
        oneway += ck.reciprocity(doc, t, refs)
    if sidecar is not None and sidecar.exists():
        assertions += ck.sidecar(sidecar)

    for a in assertions:
        for p in a.problems:
            problems.append((a.where, a.line, a.key, p))

    by_key: dict[str, list[Assertion]] = {}
    for a in assertions:
        if a.key:
            by_key.setdefault(a.key, []).append(a)
    conflicts = []
    for key, items in sorted(by_key.items()):
        if len({a.value for a in items}) > 1:
            for a in sorted(items, key=lambda a: (a.value, a.where, a.line)):
                conflicts.append((key, a.value, a.where, a.line, a.date, a.source))

    out = []
    for d in sorted(missing_docs):
        out.append(f'MISSING-DOC\t{d}')
    for d, ln, kind, raw, detail in sorted(set(unresolved), key=lambda x: (x[0], x[1], x[2], x[3])):
        out.append(f'UNRESOLVED\t{d}:{ln}\t{kind}\t{raw}\t{detail}')
    for src, tgt, d, ln in sorted(set(oneway), key=lambda x: (x[2], x[3], x[0], x[1])):
        out.append(f'ONE-WAY\t{src} -> {tgt}\t{d}:{ln}\t{tgt} does not link back to {src}')
    for where, ln, key, p in sorted(set(problems)):
        out.append(f'ASSERTION\t{where}:{ln}\t{key}\t{p}')
    for key, value, where, ln, date, source in conflicts:
        out.append(f'CONFLICT\t{key}\t{value}\t{where}:{ln}\t{date}\t{source}')
    for d, ln, kind, raw, detail in sorted(set(unchecked), key=lambda x: (x[0], x[1], x[2], x[3])):
        out.append(f'UNCHECKED\t{d}:{ln}\t{kind}\t{raw}\t{detail}')
    conflict_keys = sorted({c[0] for c in conflicts})
    out.append(
        f'summary\tdocuments={len(set(docs)) - len(missing_docs)}/{len(set(docs))}'
        f'\treferences ok={counts["ok"]} unresolved={counts["unresolved"]} unchecked={counts["unchecked"]}'
        f'\tone-way={len(set(oneway))}\tassertions={len(assertions)} with-problems={len({(p[0], p[1], p[2]) for p in problems})}'
        f'\tconflicts={len(conflict_keys)}' + (f' ({", ".join(conflict_keys)})' if conflict_keys else ''))
    failures = len(missing_docs) + len(set(unresolved)) + len(set(oneway)) + len(set(problems)) + len(conflict_keys)
    return Result(out, failures)


def load_trails(path: Path) -> dict[int, str]:
    out = {}
    for line in path.read_text(encoding='utf-8').splitlines():
        if not line.strip() or line.startswith('#') or line.startswith('number\t'):
            continue
        n, _, title = line.partition('\t')
        out[int(n)] = title
    return out


def load_case(path: Path) -> list[Doc]:
    return [Doc.parse(l.strip()) for l in path.read_text(encoding='utf-8').splitlines()
            if l.strip() and not l.startswith('#')]


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.split('\n\n')[0])
    sub = ap.add_subparsers(dest='cmd')
    c = sub.add_parser('check', help='check documents (the default)')
    c.add_argument('docs', nargs='*', help='repo[@ref]:path')
    c.add_argument('--case', type=Path, help='file listing one repo[@ref]:path per line')
    c.add_argument('--repos', type=Path, default=DEFAULT_REPOS)
    c.add_argument('--assertions', type=Path, default=DEFAULT_ASSERTIONS)
    c.add_argument('--questions', default=DEFAULT_QUESTIONS)
    c.add_argument('--trails', type=Path, help='TSV snapshot: number<TAB>title')
    c.add_argument('--home', default='praxis')
    c.add_argument('--report', action='store_true', help='print findings, always exit 0')
    d = sub.add_parser('digest', help='SHA-256 of an escaped quote, for a sidecar row')
    d.add_argument('quote')
    args = ap.parse_args(argv if argv is not None else (sys.argv[1:] or ['check', '-h']))
    if args.cmd == 'digest':
        print(sha256(unescape(args.quote)))
        return 0
    if args.cmd != 'check':
        ap.print_help()
        return 2
    docs = [Doc.parse(s) for s in args.docs]
    if args.case:
        docs += load_case(args.case)
    if not docs:
        print('no documents given', file=sys.stderr)
        return 2
    repos = Repos.load(args.repos, args.home)
    trails = load_trails(args.trails) if args.trails else None
    res = run(docs, repos, Doc.parse(args.questions), args.assertions, trails)
    sys.stdout.write('\n'.join(res.lines) + '\n')
    return 0 if args.report or res.failures == 0 else 1


if __name__ == '__main__':
    sys.exit(main())

